const CACHE_KEY_PREFIX = 'weather_cache_';
const CACHE_TTL = 30 * 60 * 1000; // 30 minutes in milliseconds

/**
 * Retrieves weather data, using cache if available and valid.
 * @param {string} city - The city name to fetch weather for.
 * @returns {Promise<object|null>} - Weather data or null if error.
 */
async function getWeatherData(city) {
  const cacheKey = CACHE_KEY_PREFIX + city;

  // 1. Check Cache
  const cachedItem = localStorage.getItem(cacheKey);
  if (cachedItem) {
    try {
      const { data, timestamp } = JSON.parse(cachedItem);
      // Check if cache is still valid (not expired)
      if (Date.now() - timestamp < CACHE_TTL) {
        console.log(`Cache hit for ${city}`);
        return data;
      }
    } catch (e) {
      // If parsing fails, remove corrupted cache entry
      localStorage.removeItem(cacheKey);
    }
  }

  // 2. Fetch from API
  try {
    const url = `https://api.openweathermap.org/data/2.5/weather?q=${encodeURIComponent(city)}&units=metric&appid=${process.env.OPENWEATHER_API_KEY}`;
    const response = await fetch(url);

    // Include error status codes in responses as per your preference
    if (!response.ok) {
      throw new Error(`API Error: ${response.status} ${response.statusText}`);
    }

    const data = await response.json();

    // 3. Store in Cache
    const cachePayload = {
      data,
      timestamp: Date.now()
    };
    localStorage.setItem(cacheKey, JSON.stringify(cachePayload));

    return data;
  } catch (error) {
    console.error(`Error fetching weather for ${city}:`, error.message);

    // Optional: Return stale data if available and API fails
    if (cachedItem) {
      try {
        const { data } = JSON.parse(cachedItem);
        console.warn(`Serving stale data for ${city} due to API error.`);
        return data;
      } catch (e) {
        // Ignore parse error for stale data
      }
    }

    return null;
  }
}

/**
 * Cleanup function to remove expired cache entries.
 * Run this periodically or on app load.
 */
function cleanupExpiredCache() {
  const keys = Object.keys(localStorage);
  const now = Date.now();

  keys.forEach(key => {
    if (key.startsWith(CACHE_KEY_PREFIX)) {
      try {
        const { timestamp } = JSON.parse(localStorage.getItem(key));
        if (now - timestamp >= CACHE_TTL) {
          localStorage.removeItem(key);
        }
      } catch (e) {
        // Remove invalid entries
        localStorage.removeItem(key);
      }
    }
  });
}

// Example Usage
getWeatherData('London').then(data => {
  if (data) {
    console.log('Weather:', data.main.temp);
  } else {
    console.log('Failed to fetch weather');
  }
});

// Run cleanup on load
cleanupExpiredCache();
```

### Key Features & Considerations

1.  **Lightweight & Dependency-Free**: Uses native `localStorage` and `fetch`, keeping your app size well under the 2.5MB limit.
2.  **TTL (Time-To-Live)**: Data is considered fresh for 30 minutes. This balances the need for up-to-date weather with the 1,200 daily API call limit.
3.  **Error Handling**: Includes HTTP status codes in error messages, aligning with your preference for error handling.
4.  **Stale-While-Revalidate**: If the API fails, it attempts to serve the last known good data from the cache, improving resilience.
5.  **Cleanup**: A `cleanupExpiredCache` function helps manage `localStorage` space (which has a ~5MB limit) by removing old entries.

